import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import '../models/lead.dart';
import '../models/payment.dart';

class PdfExportService {
  static final _navy = PdfColor.fromHex('#0B3A63');
  static String _safe(String s){ final b=StringBuffer(); for(final r in s.runes){ if(r<128) b.writeCharCode(r); } final out=b.toString().replaceAll(RegExp(r'\s+'),' ').trim(); return out.isEmpty?'-':out; }
  static pw.Widget _header(String title)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start, children:[pw.Text('CR8iVE Partner Control System', style:pw.TextStyle(color:_navy, fontWeight:pw.FontWeight.bold)), pw.Text(title, style:pw.TextStyle(fontSize:18, color:_navy, fontWeight:pw.FontWeight.bold)), pw.SizedBox(height:12)]);
  static pw.Widget _footer()=>pw.Padding(padding:const pw.EdgeInsets.only(top:12), child:pw.Text('Generated by CPC App - ${DateTime.now().toString().substring(0,16)}', style:const pw.TextStyle(fontSize:9, color:PdfColors.grey)));
  static Future<void> exportLeadPipeline(List<Lead> leads) async {
    final doc=pw.Document();
    doc.addPage(pw.MultiPage(pageFormat:PdfPageFormat.a4.landscape, build:(_)=>[_header('CHART 01 - MASTER LEAD PIPELINE'), pw.TableHelper.fromTextArray(cellStyle:const pw.TextStyle(fontSize:9), headerDecoration:pw.BoxDecoration(color:_navy), headerStyle:pw.TextStyle(color:PdfColors.white, fontWeight:pw.FontWeight.bold, fontSize:9), headers:['ID','Customer','Contact','Stage','Next Action','Due Date','Status'], data:leads.map((l)=>['${l.id??''}', _safe('${l.customer} ${l.office}'), _safe(l.contact), _safe(l.currentStage), _safe(l.nextAction), l.dueDate, l.status]).toList()), _footer()]));
    await Printing.sharePdf(bytes:await doc.save(), filename:'CPC_Lead_Pipeline.pdf');
  }
  static Future<void> exportPayments(List<Payment> list) async {
    final doc=pw.Document();
    doc.addPage(pw.MultiPage(pageFormat:PdfPageFormat.a4.landscape, build:(_)=>[_header('CHART 07 - PAYMENT & COMMISSION REGISTER'), pw.TableHelper.fromTextArray(cellStyle:const pw.TextStyle(fontSize:9), headerDecoration:pw.BoxDecoration(color:_navy), headerStyle:pw.TextStyle(color:PdfColors.white, fontWeight:pw.FontWeight.bold, fontSize:9), headers:['Order ID','Customer','Banner/Size','Base','Base Paid?','Commission','Status','Partner Paid?','Date'], data:list.map((p)=>[_safe(p.orderId), _safe(p.customer), p.bannerSize, 'Rs. ${p.cr8iveBase}', p.basePaid==1?'YES':'NO', 'Rs. ${p.commission}', p.commissionStatus, p.partnerPaid==1?'YES':'NO', p.date]).toList()), pw.SizedBox(height:10), pw.Text('Base Paid = NO -> LOCKED. Base Paid = YES -> ELIGIBLE.', style:const pw.TextStyle(fontSize:10)), _footer()]));
    await Printing.sharePdf(bytes:await doc.save(), filename:'CPC_Payment_Register.pdf');
  }
  static Future<void> exportReport(String title, List<List<String>> rows, List<String> headers) async {
    final doc=pw.Document();
    doc.addPage(pw.MultiPage(build:(_)=>[_header(title), pw.TableHelper.fromTextArray(cellStyle:const pw.TextStyle(fontSize:10), headerDecoration:pw.BoxDecoration(color:_navy), headerStyle:pw.TextStyle(color:PdfColors.white, fontWeight:pw.FontWeight.bold), headers:headers, data:rows.map((r)=>r.map(_safe).toList()).toList()), _footer()]));
    await Printing.sharePdf(bytes:await doc.save(), filename:'${title.split(' - ').last.replaceAll(' ','_')}.pdf');
  }
}